import{_ as l,c as r,o as t,ag as e}from"./chunks/framework.DQvKz0xt.js";const p=JSON.parse('{"title":"滚动 (Scrolling) - Rive 编辑器","description":"布局 (Layouts) Rive 的滚动功能通过两个新约束实现：一个用于为溢出内容添加触摸滚动，另一个用于创建滚动条。这两个约束都与现有的布局组件协同工作。未来我们将提供更通用的滚动组件以简化设置。","frontmatter":{"title":"滚动 (Scrolling) - Rive 编辑器","description":"布局 (Layouts) Rive 的滚动功能通过两个新约束实现：一个用于为溢出内容添加触摸滚动，另一个用于创建滚动条。这两个约束都与现有的布局组件协同工作。未来我们将提供更通用的滚动组件以简化设置。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 布局, 滚动"}]]},"headers":[],"relativePath":"editor/layouts/scrolling.md","filePath":"editor/layouts/scrolling.md","lastUpdated":1774838907000}'),o={name:"editor/layouts/scrolling.md"};function i(n,a,s,c,h,d){return t(),r("div",null,[...a[0]||(a[0]=[e('<p>布局 (Layouts)</p><h1 id="滚动-scrolling" tabindex="-1">滚动 (Scrolling) <a class="header-anchor" href="#滚动-scrolling" aria-label="Permalink to &quot;滚动 (Scrolling)&quot;">​</a></h1><p>Rive 的滚动功能通过两个新约束实现：一个用于为溢出内容添加触摸滚动，另一个用于创建滚动条。这两个约束都与现有的布局组件协同工作。未来我们将提供更通用的滚动组件以简化设置。</p><p>注意：目前尚不支持鼠标滚轮/触控板手势，但这已列入 v1 路线图。</p><hr><h2 id="​-内容滚动-content-scrolling" tabindex="-1"><a href="#content-scrolling">​</a> 内容滚动 (Content Scrolling) <a class="header-anchor" href="#​-内容滚动-content-scrolling" aria-label="Permalink to &quot;[​](#content-scrolling) 内容滚动 (Content Scrolling)&quot;">​</a></h2><p>要创建滚动区域，请建立如下层级：</p><ul><li><strong>滚动视图 (Scroll view)</strong>：定义滚动区域大小的布局。</li><li><strong>滚动内容 (Scroll content)</strong>：包含滚动项的布局（在该布局上应用“滚动约束”）。滚动量由该布局的大小决定。通常设为包裹 (Hug) 或固定 (Fixed)。</li><li><strong>滚动项 (Scroll items)</strong>：要滚动的具体布局项。</li></ul><p>选中你的“滚动内容”布局，在检查器中添加“滚动内容约束 (Scroll Content constraint)”。</p><h4 id="​-方向" tabindex="-1"><a href="#direction">​</a> 方向 <a class="header-anchor" href="#​-方向" aria-label="Permalink to &quot;[​](#direction) 方向&quot;">​</a></h4><ul><li><strong>垂直 (Vertical)</strong> / <strong>水平 (Horizontal)</strong> / <strong>全部 (All)</strong>。</li></ul><h4 id="​-滚动百分比-可动画" tabindex="-1"><a href="#scroll-percent-x/y-animatable">​</a> 滚动百分比 (可动画) <a class="header-anchor" href="#​-滚动百分比-可动画" aria-label="Permalink to &quot;[​](#scroll-percent-x/y-animatable) 滚动百分比 (可动画)&quot;">​</a></h4><p>设置 0% 到 100% 的滚动位置。可以在时间轴上打关键帧。</p><h4 id="​-滚动索引-可动画" tabindex="-1"><a href="#scroll-index-animatable">​</a> 滚动索引 (可动画) <a class="header-anchor" href="#​-滚动索引-可动画" aria-label="Permalink to &quot;[​](#scroll-index-animatable) 滚动索引 (可动画)&quot;">​</a></h4><p>设置滚动到第几个项目的索引（从 0 开始）。仅适用于单向滚动。</p><h4 id="​-物理效果" tabindex="-1"><a href="#physics">​</a> 物理效果 <a class="header-anchor" href="#​-物理效果" aria-label="Permalink to &quot;[​](#physics) 物理效果&quot;">​</a></h4><ul><li><strong>弹性 (Elastic)</strong>：iOS 风格的滚动，带有减速和边缘回弹。</li><li><strong>夹紧 (Clamped)</strong>：基础的拖拽，无物理效果。</li></ul><h4 id="​-吸附-snap" tabindex="-1"><a href="#snap">​</a> 吸附 (Snap) <a class="header-anchor" href="#​-吸附-snap" aria-label="Permalink to &quot;[​](#snap) 吸附 (Snap)&quot;">​</a></h4><p>开启后，滚动内容将始终停留在完整项目的边缘。</p><hr><h2 id="​-列表滚动-list-scrolling" tabindex="-1"><a href="#list-scrolling">​</a> 列表滚动 (List Scrolling) <a class="header-anchor" href="#​-列表滚动-list-scrolling" aria-label="Permalink to &quot;[​](#list-scrolling) 列表滚动 (List Scrolling)&quot;">​</a></h2><p>如果滚动的是列表 (List)，设置方式相同。开启 <strong>虚拟化 (Virtualize)</strong> 可以极大地提升包含大量项目时的性能。</p><hr><h2 id="​-创建滚动条" tabindex="-1"><a href="#creating-a-scroll-bar">​</a> 创建滚动条 <a class="header-anchor" href="#​-创建滚动条" aria-label="Permalink to &quot;[​](#creating-a-scroll-bar) 创建滚动条&quot;">​</a></h2><p>需要建立：</p><ul><li><strong>滚动条 (Scroll Bar)</strong>：定义滚动条轨道的布局。</li><li><strong>滚动滑块 (Scroll Thumb)</strong>：定义可拖动的滑块布局。</li></ul><p>选中滑块布局，添加“滚动条滑块约束 (Scroll Bar Thumb constraint)”，并使用目标选择器连接到上述的“滚动内容”布局。</p><p><a href="/docs/editor/layouts/n-slicing">N轴切片 (N-Slicing)</a><a href="/docs/editor/libraries">库 (Libraries)</a></p>',28)])])}const u=l(o,[["render",i]]);export{p as __pageData,u as default};
